    fn acknowledge_client_mutations_inner(
        &mut self,
        auth_fingerprint: &str,
        authority_instance_id: Option<&str>,
        ids: &[String],
    ) -> SnapbackResult<u64> {
        if ids.len() > CLIENT_MUTATION_ACK_MAX_IDS {
            return Err(SnapbackError::error(
                "SNAPBACK_CLIENT_MUTATION_ACK_LIMIT_EXCEEDED",
                "sync",
                format!(
                    "one request may acknowledge at most {CLIENT_MUTATION_ACK_MAX_IDS} client mutations"
                ),
            ));
        }
        let unique = ids.iter().collect::<BTreeSet<_>>();
        for id in &unique {
            if !replay_opaque_id_is_valid(id) {
                return Err(SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_ID_INVALID",
                    "sync",
                    "acknowledged client mutation id is invalid",
                ));
            }
        }
        if unique.is_empty() {
            return Ok(0);
        }
        let tx = self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        let (retained_records, retained_bytes) = client_mutation_retention_counters(&tx)?;
        let (auth_records, auth_bytes) =
            client_mutation_auth_retention_counters(&tx, auth_fingerprint)?;
        let mut deleted = 0_u64;
        let mut deleted_bytes = 0_u64;
        for id in unique {
            let row_bytes = tx
                .query_row(
                    "SELECT
                       length(CAST(client_mutation_id AS BLOB)) +
                       length(CAST(function AS BLOB)) +
                       length(CAST(auth_fingerprint AS BLOB)) +
                       COALESCE(length(CAST(authority_instance_id AS BLOB)), 0) +
                       length(CAST(input_fingerprint AS BLOB)) +
                       COALESCE(length(CAST(operation_issuance_json AS BLOB)), 0) +
                       length(CAST(output_json AS BLOB))
                     FROM _snapback_client_mutations
                     WHERE client_mutation_id = ?1 AND auth_fingerprint = ?2
                       AND (?3 IS NULL OR authority_instance_id = ?3)",
                    params![id, auth_fingerprint, authority_instance_id],
                    |row| row.get::<_, u64>(0),
                )
                .optional()?;
            let Some(row_bytes) = row_bytes else {
                continue;
            };
            crate::operation_ledger::acknowledge_client_operation_by_id_in(
                &tx,
                id,
                auth_fingerprint,
                authority_instance_id,
                now_millis(),
            )?;
            let removed = tx.execute(
                "DELETE FROM _snapback_client_mutations
                 WHERE client_mutation_id = ?1 AND auth_fingerprint = ?2
                   AND (?3 IS NULL OR authority_instance_id = ?3)",
                params![id, auth_fingerprint, authority_instance_id],
            )? as u64;
            deleted = deleted.saturating_add(removed);
            if removed > 0 {
                deleted_bytes = deleted_bytes.checked_add(row_bytes).ok_or_else(|| {
                    invalid_client_mutation_retention_state(
                        "acknowledged client-mutation byte count overflowed",
                    )
                })?;
            }
        }
        if deleted > 0 {
            let records = retained_records.checked_sub(deleted).ok_or_else(|| {
                invalid_client_mutation_retention_state(
                    "acknowledgement would underflow the retained record counter",
                )
            })?;
            let bytes = retained_bytes.checked_sub(deleted_bytes).ok_or_else(|| {
                invalid_client_mutation_retention_state(
                    "acknowledgement would underflow the retained byte counter",
                )
            })?;
            save_meta_u64(&tx, META_CLIENT_MUTATION_RECORDS, records)?;
            save_meta_u64(&tx, META_CLIENT_MUTATION_BYTES, bytes)?;
            let auth_records = auth_records.checked_sub(deleted).ok_or_else(|| {
                invalid_client_mutation_retention_state(
                    "acknowledgement would underflow the auth record counter",
                )
            })?;
            let auth_bytes = auth_bytes.checked_sub(deleted_bytes).ok_or_else(|| {
                invalid_client_mutation_retention_state(
                    "acknowledgement would underflow the auth byte counter",
                )
            })?;
            save_client_mutation_auth_retention_counters(
                &tx,
                auth_fingerprint,
                auth_records,
                auth_bytes,
            )?;
            let gc_total = optional_meta_u64(&tx, META_CLIENT_MUTATION_GC_TOTAL)?
                .unwrap_or(0)
                .checked_add(deleted)
                .ok_or_else(|| {
                    invalid_client_mutation_retention_state(
                        "client-mutation acknowledgement total overflowed",
                    )
                })?;
            save_meta_u64(&tx, META_CLIENT_MUTATION_GC_TOTAL, gc_total)?;
        }
        tx.commit()?;
        Ok(deleted)
    }

    /// Administrative recovery for a client that can no longer send durable
    /// acknowledgements. Purging deliberately gives up full-result replay for
    /// removed settlements; covered operations retain compact duplicate
    /// prevention while predecessor-only rows retain the legacy tradeoff.
    /// Callers must gate this as an admin write. Ledger rows, purge audit, and
    /// global/per-auth counters change in one transaction.
    pub fn purge_client_mutation_settlements(
        &mut self,
        auth_fingerprint: Option<&str>,
    ) -> SnapbackResult<u64> {
        let tx = self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        let (retained_records, retained_bytes) = client_mutation_retention_counters(&tx)?;
        let deleted = match auth_fingerprint {
            Some(auth_fingerprint) => {
                let (auth_records, auth_bytes) =
                    client_mutation_auth_retention_counters(&tx, auth_fingerprint)?;
                let settlements = tx
                    .prepare(
                        "SELECT client_mutation_id,auth_fingerprint,authority_instance_id
                           FROM _snapback_client_mutations
                          WHERE auth_fingerprint=?1 ORDER BY client_mutation_id",
                    )?
                    .query_map(params![auth_fingerprint], |row| {
                        Ok((row.get(0)?, row.get(1)?, row.get(2)?))
                    })?
                    .collect::<rusqlite::Result<Vec<(String, String, Option<String>)>>>()?;
                let selector_digest = crate::operation_ledger::digest_fact_set(
                    b"snapback:operation-purge-selector:v1\n",
                    &json!({ "authFingerprint": auth_fingerprint }),
                );
                crate::operation_ledger::operator_purge_client_operations_in(
                    &tx,
                    "auth",
                    &selector_digest,
                    &settlements,
                    now_millis(),
                )?;
                let deleted = tx.execute(
                    "DELETE FROM _snapback_client_mutations WHERE auth_fingerprint = ?1",
                    params![auth_fingerprint],
                )? as u64;
                if deleted != auth_records {
                    return Err(invalid_client_mutation_retention_state(
                        "auth purge row count did not match its retention counter",
                    ));
                }
                save_meta_u64(
                    &tx,
                    META_CLIENT_MUTATION_RECORDS,
                    retained_records.checked_sub(auth_records).ok_or_else(|| {
                        invalid_client_mutation_retention_state(
                            "auth purge would underflow the global record counter",
                        )
                    })?,
                )?;
                save_meta_u64(
                    &tx,
                    META_CLIENT_MUTATION_BYTES,
                    retained_bytes.checked_sub(auth_bytes).ok_or_else(|| {
                        invalid_client_mutation_retention_state(
                            "auth purge would underflow the global byte counter",
                        )
                    })?,
                )?;
                save_client_mutation_auth_retention_counters(&tx, auth_fingerprint, 0, 0)?;
                deleted
            }
            None => {
                let settlements = tx
                    .prepare(
                        "SELECT client_mutation_id,auth_fingerprint,authority_instance_id
                           FROM _snapback_client_mutations ORDER BY client_mutation_id",
                    )?
                    .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
                    .collect::<rusqlite::Result<Vec<(String, String, Option<String>)>>>()?;
                let selector_digest = crate::operation_ledger::digest_fact_set(
                    b"snapback:operation-purge-selector:v1\n",
                    &json!({ "all": true }),
                );
                crate::operation_ledger::operator_purge_client_operations_in(
                    &tx,
                    "all",
                    &selector_digest,
                    &settlements,
                    now_millis(),
                )?;
                let deleted = tx.execute("DELETE FROM _snapback_client_mutations", [])? as u64;
                if deleted != retained_records {
                    return Err(invalid_client_mutation_retention_state(
                        "global purge row count did not match its retention counter",
                    ));
                }
                tx.execute("DELETE FROM _snapback_client_mutation_auth_retention", [])?;
                save_meta_u64(&tx, META_CLIENT_MUTATION_RECORDS, 0)?;
                save_meta_u64(&tx, META_CLIENT_MUTATION_BYTES, 0)?;
                deleted
            }
        };
        tx.commit()?;
        Ok(deleted)
    }

    /// Return the durably settled result for a client mutation identity.
    /// Function/auth mismatches fail closed instead of treating the key as a
    /// cache hit under different authority.
    pub fn client_mutation_result(
        &self,
        identity: &ClientMutationIdentity,
    ) -> SnapbackResult<Option<MutationOutput>> {
        validate_client_mutation_identity(identity)?;
        with_pinned_read_snapshot(&self.conn, |conn| {
            let row: Option<RetainedClientMutationRow> = conn
                .query_row(
                    "SELECT function, auth_fingerprint, authority_instance_id,
                        input_fingerprint, operation_issuance_json, output_json,
                        settled_version, settled_version_exact
                 FROM _snapback_client_mutations WHERE client_mutation_id = ?1",
                    params![identity.id],
                    |row| {
                        Ok(RetainedClientMutationRow {
                            function: row.get(0)?,
                            auth_fingerprint: row.get(1)?,
                            authority_instance_id: row.get(2)?,
                            input_fingerprint: row.get(3)?,
                            operation_issuance_json: row.get(4)?,
                            output_json: row.get(5)?,
                            settled_version: row.get(6)?,
                            settled_version_exact: row.get(7)?,
                        })
                    },
                )
                .optional()?;
            let Some(RetainedClientMutationRow {
                function,
                auth_fingerprint: retained_auth,
                authority_instance_id: retained_authority,
                input_fingerprint: retained_input,
                operation_issuance_json: retained_issuance,
                output_json,
                settled_version,
                settled_version_exact: exact_settled_version,
            }) = row
            else {
                return covered_operation_recovery_result(conn, identity);
            };
            if function != identity.function {
                return Err(SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_ID_REUSED",
                    "sync",
                    "client mutation id was already used for another function",
                )
                .with_details(json!({
                    "clientMutationId": identity.id,
                    "expectedFunction": function,
                    "actualFunction": identity.function,
                })));
            }
            if retained_auth != identity.auth_fingerprint {
                if retained_auth.starts_with("fnv1a:") {
                    return Err(SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_LEGACY_AUTH_QUARANTINED",
                    "auth",
                    "client mutation uses a legacy auth fingerprint that cannot be rebound safely; acknowledge the consumed result or use the admin purge recovery path",
                )
                .with_details(json!({ "clientMutationId": identity.id })));
                }
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_STALE_RESULT",
                    "auth",
                    "client mutation was recorded under another auth context",
                )
                .with_details(json!({ "clientMutationId": identity.id })));
            }
            let Some(retained_authority) = retained_authority else {
                return Err(SnapbackError::error(
                "SNAPBACK_CLIENT_MUTATION_LEGACY_AUTH_QUARANTINED",
                "auth",
                "client mutation predates authority descriptors and cannot be rebound safely; acknowledge the consumed result or use the admin purge recovery path",
            )
            .with_details(json!({ "clientMutationId": identity.id })));
            };
            if retained_authority != identity.authority_instance_id {
                return Err(SnapbackError::error(
                "SNAPBACK_AUTH_STALE_RESULT",
                "auth",
                "client mutation was settled under another authority instance; discard it or explicitly re-record it under the current authority",
            )
            .with_details(json!({
                "clientMutationId": identity.id,
                "reason": "authority_instance_mismatch",
                "guidance": "discard_or_rerecord",
                "automaticRetry": false,
            })));
            }
            if retained_input != identity.input_fingerprint {
                return Err(SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_ID_REUSED",
                    "sync",
                    "client mutation id was already used with another mutation payload",
                )
                .with_details(json!({
                    "clientMutationId": identity.id,
                    "reason": "input_fingerprint_mismatch",
                })));
            }
            let proposed_issuance = identity
                .operation_issuance
                .as_ref()
                .map(serde_json::to_string)
                .transpose()
                .map_err(|_| {
                    invalid_client_mutation_retention_state(
                        "proposed operation issuance could not be encoded",
                    )
                })?;
            if retained_issuance != proposed_issuance {
                return Err(SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_ID_REUSED",
                    "sync",
                    "client mutation id was reused with different operation issuance facts",
                )
                .with_details(json!({ "clientMutationId": identity.id })));
            }
            let output_value = serde_json::from_str::<Value>(&output_json).map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_RESULT_INVALID",
                    "storage",
                    "stored client mutation result could not be decoded",
                )
                .with_details(json!({
                    "clientMutationId": identity.id,
                    "error": error.to_string(),
                }))
            })?;
            let head = current_version_on(conn)?;
            let output_version = decode_json_storage_version(
                output_value.get("version"),
                "stored client mutation result version",
            )
            .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
            let settled_version = decode_required_storage_version(
                settled_version,
                "stored client mutation settlement version",
            )
            .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
            let exact_settled_version = decode_optional_storage_version(
                exact_settled_version,
                "stored client mutation exact settlement version",
            )
            .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
            validate_storage_version_at_most(
                output_version,
                head,
                "stored client mutation result version",
            )
            .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
            validate_storage_version_at_most(
                settled_version,
                head,
                "stored client mutation settlement version",
            )
            .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
            if let Some(exact_settled_version) = exact_settled_version {
                validate_storage_version_at_most(
                    exact_settled_version,
                    head,
                    "stored client mutation exact settlement version",
                )
                .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
                if exact_settled_version != settled_version
                    || exact_settled_version != output_version
                {
                    return Err(SnapbackError::error(
                        "SNAPBACK_STORAGE_VERSION_CORRUPT",
                        "storage",
                        "stored client mutation result disagrees with its authoritative settlement version",
                    )
                    .with_detail("clientMutationId", identity.id.clone())
                    .with_detail("settledVersion", settled_version)
                    .with_detail("exactSettledVersion", exact_settled_version)
                    .with_detail("outputVersion", output_version));
                }
            } else if settled_version != 0 && settled_version != output_version {
                // Rows written before exact settlement metadata use zero as the
                // migration sentinel. A nullable authoritative column preserves
                // those rows without letting a newly written version-zero result
                // inherit the same ambiguity.
                return Err(SnapbackError::error(
                    "SNAPBACK_STORAGE_VERSION_CORRUPT",
                    "storage",
                    "stored client mutation result disagrees with its settlement version",
                )
                .with_detail("clientMutationId", identity.id.clone())
                .with_detail("settledVersion", settled_version)
                .with_detail("outputVersion", output_version));
            }
            let output: MutationOutput = serde_json::from_value(output_value).map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_CLIENT_MUTATION_RESULT_INVALID",
                    "storage",
                    "stored client mutation result could not be decoded",
                )
                .with_details(json!({
                    "clientMutationId": identity.id,
                    "error": error.to_string(),
                }))
            })?;
            validate_retained_sequence_allocations(&output.settlement_sequence_allocations)
                .map_err(|error| error.with_detail("clientMutationId", identity.id.clone()))?;
            debug_assert_eq!(output.version, output_version);
            Ok(Some(output))
        })
    }

    pub fn current_version(&self) -> SnapbackResult<u64> {
        current_version_on(&self.conn)
    }

    /// Prune the change journal to bound its growth: delete changes that are
    /// outside **both** the version window (older than `retain_versions` behind
    /// the current version) and the time window (older than `retain_ms`). A
    /// change is kept if it is within either window, so a burst of writes and a
    /// long-idle table are both retained conservatively.
    ///
    /// A table's **newest** change is never pruned, even when cold. Read-set
    /// validation uses `MAX(version) WHERE table_name = ?` and treats
    /// captured-version-equals-current as "unchanged since the read"; if the
    /// last change of a cold table were pruned, that `MAX` would drop to 0 and
    /// spuriously conflict a mutation that only *read* the table. Retaining the
    /// per-table high-water row keeps the invariant while still bounding the
    /// journal (at most one version's worth of rows per table survives the
    /// window, and table count is bounded by the schema).
    ///
    /// @ref LLP 0008#retention-and-resume — version-and-time-bounded retention.
    /// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L3.
    pub fn prune_change_journal(
        &self,
        now_ms: u64,
        retain_versions: u64,
        retain_ms: u64,
    ) -> SnapbackResult<u64> {
        // Validate the supplied clock before arithmetic. Saturation is useful
        // for an ordinary window larger than the current age, but it must not
        // turn a non-portable caller value into an apparently valid floor.
        validate_portable_timestamp_millis(now_ms)?;
        let tx = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let head = current_version_on(&tx)?;
        let mut version_floor = head.saturating_sub(retain_versions);
        // @ref LLP 0073#rebuilds-and-migrations — an unexpired derived-index
        // journal-floor lease prevents pruning the suffix an approved catch-up
        // operation still needs. A snapshot at S needs every change > S, so
        // pruning may advance through S but no farther.
        let vector_lease_floor: Option<i64> = tx.query_row(
            "SELECT MIN(floor_version) FROM _snapback_vector_journal_leases
             WHERE expires_at_ms >= ?1",
            params![timestamp_to_sql_millis(now_ms)?],
            |row| row.get(0),
        )?;
        if let Some(vector_lease_floor) = vector_lease_floor {
            let vector_lease_floor = decode_required_storage_version(
                SqlValue::Integer(vector_lease_floor),
                "vector journal lease floor",
            )?;
            version_floor = version_floor.min(next_storage_version(vector_lease_floor)?);
        }
        let version_floor = version_to_sql_integer(version_floor)?;
        let time_floor = timestamp_to_sql_millis(now_ms.saturating_sub(retain_ms))?;
        // A corrupt older version can sort below both floors while a later,
        // valid row remains the prunable MAX. Validate the whole journal via
        // the partial invalid-version index before either advancing the replay
        // floor or deleting anything.
        ensure_change_journal_versions_valid(&tx, None)?;
        validate_change_journal_head(&tx, head)?;
        let existing_floor = retention_floor_at_most(&tx, head)?;
        // Predicate for a prunable row: outside both windows, and not its
        // table's high-water change (which read-set validation still needs).
        let prunable = "version < ?1 AND changed_at_ms < ?2 \
             AND version < (SELECT MAX(version) FROM _snapback_changes t2 \
                            WHERE t2.table_name = _snapback_changes.table_name)";
        // Advance the monotonic replay floor to the highest version actually
        // pruned this pass, so a resume at/above the floor is guaranteed to have
        // a contiguous journal.
        let highest_pruned: SqlValue = tx.query_row(
            &format!("SELECT MAX(version) FROM _snapback_changes WHERE {prunable}"),
            params![version_floor, time_floor],
            |row| row.get(0),
        )?;
        if let Some(highest_pruned) = decode_optional_storage_version(
            highest_pruned,
            "highest prunable change-journal version",
        )? {
            let floor = existing_floor.max(next_storage_version(highest_pruned)?);
            save_retention_floor_on(&tx, floor)?;
        }
        let deleted = tx.execute(
            &format!("DELETE FROM _snapback_changes WHERE {prunable}"),
            params![version_floor, time_floor],
        )?;
        tx.commit()?;
        Ok(deleted as u64)
    }

    /// The monotonic replay floor: one past the highest change version pruning
    /// has removed (0 if nothing has ever been pruned). A version-based resume
    /// below this may hit a pruned gap and must resnapshot; from at/above it the
    /// journal is contiguous. Distinct from a table's validation high-water,
    /// which pruning preserves.
    ///
    /// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L3.
    pub fn journal_floor_version(&self) -> SnapbackResult<u64> {
        with_pinned_read_snapshot(&self.conn, |conn| {
            retention_floor_at_most(conn, current_version_on(conn)?)
        })
    }

    /// Configure the legacy v1 finite table-wide `maxRows` history policy.
    /// New schema-declared history uses the distinct v2 per-record projection;
    /// capability publication remains gated by LLP 0162's corpus.
    pub fn configure_history_policy(
        &self,
        policy: &crate::proof_checkpoint::HistoryRetentionPolicyV1,
    ) -> SnapbackResult<()> {
        crate::proof_checkpoint::configure_history_policy(&self.conn, &self.schema, policy)
    }

    /// Prune only the history clock. This deliberately does not read or write
    /// the sync replay floor.
    pub fn prune_record_history(&self, now_ms: u64) -> SnapbackResult<u64> {
        crate::proof_checkpoint::prune_record_history(&self.conn, now_ms)
    }

    /// Read retained versions under current-record plus per-post-image
    /// authorization. Pagination occurs after elision so its cursor exposes
    /// only the count of versions this caller could see.
    pub fn record_history(
        &self,
        table: &str,
        row_id: &str,
        visible_offset: u64,
        limit: u32,
        authorize_current: impl FnOnce(Option<&Value>) -> bool,
        authorize_historical: impl FnMut(Option<&Value>) -> bool,
    ) -> SnapbackResult<crate::proof_checkpoint::RecordHistoryPageV1> {
        with_pinned_read_snapshot(&self.conn, |conn| {
            let current = get_on(conn, &self.schema, table, row_id)?;
            crate::proof_checkpoint::read_record_history(
                conn,
                table,
                row_id,
                visible_offset,
                limit,
                current.as_ref(),
                authorize_current,
                authorize_historical,
            )
        })
    }

    /// Create a receipt-only or materialized named checkpoint. Materialized
    /// creation is admitted only for file-backed databases and always uses a
    /// finite copy/WAL/lease request.
    pub fn create_named_checkpoint(
        &mut self,
        destination: Option<&Path>,
        request: &crate::proof_checkpoint::NamedCheckpointRequestV1,
    ) -> SnapbackResult<crate::proof_checkpoint::NamedCheckpointReceiptV1> {
        self.create_named_checkpoint_with_cut(destination, request, None)
    }

    fn create_named_checkpoint_with_cut(
        &mut self,
        destination: Option<&Path>,
        request: &crate::proof_checkpoint::NamedCheckpointRequestV1,
        cut_at: Option<crate::proof_checkpoint::CheckpointPublicationCut>,
    ) -> SnapbackResult<crate::proof_checkpoint::NamedCheckpointReceiptV1> {
        let source = self.path.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_CHECKPOINT_SOURCE_UNSUPPORTED",
                "proofCheckpoint",
                "named checkpoints require a file-backed database",
            )
        })?;
        // Initialize the stream before pinning. It is part of the compared
        // checkpoint header and cannot be minted after the source scan.
        let _ = self.data_version_stream()?;
        crate::proof_checkpoint::create_named_checkpoint(
            &self.conn,
            &source,
            &self.schema,
            destination,
            request,
            cut_at,
        )
    }

    #[cfg(test)]
    pub(crate) fn create_named_checkpoint_at_cut_for_test(
        &mut self,
        destination: Option<&Path>,
        request: &crate::proof_checkpoint::NamedCheckpointRequestV1,
        cut_at: crate::proof_checkpoint::CheckpointPublicationCut,
    ) -> SnapbackResult<crate::proof_checkpoint::NamedCheckpointReceiptV1> {
        self.create_named_checkpoint_with_cut(destination, request, Some(cut_at))
    }

    pub fn inspect_named_checkpoint(
        &self,
        checkpoint_id: &str,
        now_ms: u64,
    ) -> SnapbackResult<crate::proof_checkpoint::NamedCheckpointReceiptV1> {
        crate::proof_checkpoint::inspect_checkpoint(&self.conn, checkpoint_id, now_ms)
    }

    pub fn erase_named_checkpoint(
        &self,
        checkpoint_id: &str,
        now_ms: u64,
    ) -> SnapbackResult<crate::proof_checkpoint::CheckpointRegistryRecordV1> {
        crate::proof_checkpoint::erase_checkpoint(&self.conn, checkpoint_id, now_ms)
    }

    /// Invalidate and destroy every registered materialized checkpoint copy
    /// that could retain a protected record. Retrying `operation_id` resumes
    /// explicit unreachable/crash obligations instead of re-enumerating a
    /// weaker inventory.
    pub fn erase_protected_record_checkpoint_copies(
        &self,
        qualified_table: &str,
        row_id: &str,
        operation_id: &str,
        now_ms: u64,
    ) -> SnapbackResult<
        crate::proof_checkpoint::ProtectedRecordCheckpointErasureReceiptV1,
    > {
        crate::proof_checkpoint::erase_protected_record_checkpoint_copies(
            &self.conn,
            qualified_table,
            row_id,
            operation_id,
            now_ms,
        )
    }

    pub fn recover_named_checkpoint(
        &self,
        checkpoint_id: &str,
        now_ms: u64,
    ) -> SnapbackResult<crate::proof_checkpoint::CheckpointRegistryRecordV1> {
        crate::proof_checkpoint::recover_checkpoint(&self.conn, checkpoint_id, now_ms)
    }

    pub fn change_journal_len(&self) -> SnapbackResult<u64> {
        let count: i64 =
            self.conn
                .query_row("SELECT COUNT(*) FROM _snapback_changes", [], |row| {
                    row.get(0)
                })?;
        Ok(count as u64)
    }

    /// Whether a client must resnapshot rather than replay. `from_version` is
    /// the earliest change version the client still needs (it has applied every
    /// version before it, and wants `[from_version, current]`). If that is below
    /// the monotonic replay floor, a needed change may have been pruned, so the
    /// client must resnapshot; at/above the floor the journal is contiguous and
    /// can be replayed. A floor of 0 (nothing ever pruned) never forces a
    /// resnapshot.
    ///
    /// This is the retention contract for the version-based replay path; the
    /// consumer is future sync work ([LLP 0032](./0032-decision-and-implementation-hardening.plan.md)
    /// P4 / DK-3), and this primitive keeps the floor authoritative meanwhile.
    ///
    /// @ref LLP 0008#retention-and-resume — resume below the retained floor requires resnapshot.
    /// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L3.
    pub fn resume_requires_resnapshot(&self, from_version: u64) -> SnapbackResult<bool> {
        Ok(from_version < self.journal_floor_version()?)
    }

    /// Distinct row ids journaled for `table` strictly after `version` — the
    /// rung-2 replay's journal-affected id set (LLP 0090 D1.3): only these
    /// ids are touched in the accumulator update; untouched witness leaves
    /// remain. Returns at most `limit + 1` ids, so a caller comparing against
    /// its replay-vs-replace threshold detects "over threshold" without
    /// unbounded work. The caller must already have checked
    /// `resume_requires_resnapshot` — below the retained floor, absence from
    /// the journal proves nothing.
    pub fn changed_row_ids_for_table_since(
        &self,
        table: &str,
        version: u64,
        limit: usize,
    ) -> SnapbackResult<Vec<String>> {
        let table = schema_table(&self.schema, table)?;
        let mut statement = self.conn.prepare_cached(
            "SELECT DISTINCT row_id FROM _snapback_changes \
             WHERE table_name = ?1 AND version > ?2 LIMIT ?3",
        )?;
        let version = version_to_sql_integer(version)?;
        let fetch = i64::try_from(limit.saturating_add(1)).unwrap_or(i64::MAX);
        let rows = statement.query_map(params![table.name, version, fetch], |row| {
            row.get::<_, String>(0)
        })?;
        let mut ids = Vec::new();
        for row in rows {
            ids.push(row?);
        }
        Ok(ids)
    }

    /// The `EXPLAIN QUERY PLAN` detail for the per-mutation read-set validation
    /// query, so a test can assert it uses the `(table_name, version)` index
    /// rather than scanning.
    /// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L3 index gate.
    pub fn explain_table_change_version_plan(&self, table: &str) -> SnapbackResult<String> {
        let table = schema_table(&self.schema, table)?;
        let mut statement = self.conn.prepare(
            "EXPLAIN QUERY PLAN SELECT MAX(version) FROM _snapback_changes WHERE table_name = ?1",
        )?;
        let rows = statement.query_map(params![table.name], |row| row.get::<_, String>(3))?;
        let mut detail = String::new();
        for row in rows {
            detail.push_str(&row?);
            detail.push('\n');
        }
        Ok(detail)
    }

    pub fn apply_schema(&mut self, manifest: SchemaManifest) -> SnapbackResult<Vec<Diagnostic>> {
        let _writer_token = self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::SchemaActivation)?;
        self.apply_schema_mode_aware(manifest)?;
        self.writer_authority.set_schema(&self.schema)?;
        Ok(Vec::new())
    }

    pub fn reset(&mut self) -> SnapbackResult<()> {
        self.reset_and_seed(None).map(|_| ())
    }

    /// Replace all app data with an optional declarative seed in one SQLite
    /// transaction. Validation, inserts, version reset, and seed changes are
    /// all covered by the same commit: any error drops the transaction and
    /// leaves the previous database byte-for-byte visible to callers.
    ///
    /// @ref LLP 0003#execution-and-write-semantics — a logical mutation has
    /// one durable commit boundary; reset+seed is one operation, not a
    /// committed reset followed by a fallible second mutation.
    pub fn reset_and_seed(
        &mut self,
        seed: Option<SeedData>,
    ) -> SnapbackResult<Option<MutationOutput>> {
        let _writer_token = self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::ResetAndSeed)?;
        use crate::auth::coordinator::AuthCoordinator;
        use crate::auth::session_projection::{
            AuthorizationStreamRecord, ProjectionSource, SessionProjection,
        };

        let incarnation = self.ensure_authorization_stream_incarnation()?;
        // A standalone database owns no published session projection or grant
        // registry. Coordinate only its durable stream so reset remains the
        // recovery path even when the auth rows being deleted are corrupt.
        // Server-owned reset uses the installed full coordinator instead.
        let source = ProjectionSource {
            authorization_stream_value: AuthorizationStreamRecord::new(incarnation)
                .encode_bytes()?,
            restore_declaration_id: None,
            users: Vec::new(),
            identities: Vec::new(),
            sessions: Vec::new(),
            superseded_tokens: Vec::new(),
        };
        let projection =
            SessionProjection::rebuild_with_fresh_startup_id(source, now_millis(), Instant::now())?;
        let coordinator = Arc::new(AuthCoordinator::new(projection)?);
        let carrier = coordinator.premark_stream_reset_if_drained()?;
        let predecessor = carrier.predecessor().clone();
        let successor = carrier.successor().clone();
        let attempt =
            self.attempt_reset_and_seed_with_authorization_stream(seed, &predecessor, &successor);
        coordinator.finish_stream_reset(carrier, attempt)
    }

    /// Coordinated destructive reset with explicit commit certainty. A unique
    /// stream successor is the durable operation marker used to reconcile a
    /// lost COMMIT acknowledgement without replaying seed effects.
    pub(crate) fn attempt_reset_and_seed_with_authorization_stream(
        &mut self,
        seed: Option<SeedData>,
        predecessor: &crate::auth::session_projection::AuthorizationStreamIncarnation,
        successor: &crate::auth::session_projection::AuthorizationStreamIncarnation,
    ) -> auth::AuthTransactionAttempt<Option<MutationOutput>> {
        let _writer_token = match self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::ResetAndSeed)
        {
            Ok(token) => token,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        let schema = self.schema.clone();
        let authorization_interlock = self.authorization_interlock.clone();
        let tx = match self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)
        {
            Ok(tx) => tx,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error.into()),
        };
        let authorization_predecessor = match auth_stream::read_authorization_version_on(&tx) {
            Ok(version) => version,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        if authorization_predecessor
            .as_ref()
            .map(|version| version.incarnation.as_str())
            != Some(predecessor.as_str())
        {
            return auth::AuthTransactionAttempt::RolledBack(SnapbackError::error(
                "SNAPBACK_AUTH_STREAM_INCARNATION_CORRUPT",
                "auth",
                "reset coordinator predecessor does not match durable authorization state",
            ));
        }
        let seeded = match reset_and_seed_transaction(
            &tx,
            &schema,
            self.projections.as_ref(),
            &self.order_field_bounds,
            seed,
            successor,
            None,
        ) {
            Ok((seeded, None)) => seeded,
            Ok((_seeded, Some(_))) => unreachable!("legacy reset produced versioned receipt"),
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        #[cfg(test)]
        if let Err(error) = BEFORE_RESET_COMMIT_HOOK.with(|slot| {
            if let Some(hook) = slot.borrow_mut().take() {
                hook()?;
            }
            Ok::<(), SnapbackError>(())
        }) {
            return auth::AuthTransactionAttempt::RolledBack(error);
        }
        let authorization = AuthorizationCommitWitness {
            version: AuthorizationVersion {
                incarnation: successor.as_str().to_owned(),
                epoch: 0,
            },
            event: true,
            incarnation_rotated: true,
            membership_declarations: Vec::new(),
        };
        let min_commit_version = seeded.as_ref().map_or(0, |output| output.version);
        let prepared = match prepare_authorization_commit_interlock(
            &authorization,
            AuthorizationCommitImpact::AllProtectedRooms,
            authorization_interlock.as_ref(),
        ) {
            Ok(prepared) => prepared,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        match tx.commit() {
            Ok(()) => match prepared {
                Some(prepared) => match prepared.committed(min_commit_version) {
                    Ok(()) => auth::AuthTransactionAttempt::Committed(seeded),
                    Err(error) => auth::AuthTransactionAttempt::CommitUncertain(error),
                },
                None => auth::AuthTransactionAttempt::Committed(seeded),
            },
            Err(error) => {
                let error = SnapbackError::from(error);
                match auth_stream::read_authorization_version_snapshot(&self.conn) {
                    Ok(durable) if durable == Some(authorization.version.clone()) => match prepared
                    {
                        Some(prepared) => match prepared.committed(min_commit_version) {
                            Ok(()) => auth::AuthTransactionAttempt::Committed(seeded),
                            Err(error) => auth::AuthTransactionAttempt::CommitUncertain(error),
                        },
                        None => auth::AuthTransactionAttempt::Committed(seeded),
                    },
                    Ok(durable) if durable == authorization_predecessor => {
                        drop(prepared);
                        auth::AuthTransactionAttempt::RolledBack(error)
                    }
                    Ok(_) | Err(_) => {
                        if let Some(prepared) = prepared {
                            prepared.ambiguous();
                        }
                        auth::AuthTransactionAttempt::CommitUncertain(error)
                    }
                }
            }
        }
    }

    pub fn replay_versioned_seed_operation(
        &mut self,
        operation_id: &str,
        request_digest: &str,
    ) -> SnapbackResult<Option<crate::seed_identity::SeedInstallReceiptV1>> {
        let tx = self.conn.transaction()?;
        let current = crate::seed_identity::strict_current_data_version_stream(&tx)?;
        let replay = crate::seed_identity::replay_completed_operation(
            &tx,
            operation_id,
            request_digest,
            current.as_deref(),
        )?;
        tx.rollback()?;
        Ok(replay)
    }

    /// The versioned reset half of LLP 0109 rides the exact same durable
    /// transaction and commit-certainty machinery as every shipped reset.
    pub(crate) fn attempt_versioned_seed_reset_with_authorization_stream(
        &mut self,
        request: crate::seed_identity::ResetSeedRequestV1,
        predecessor: &crate::auth::session_projection::AuthorizationStreamIncarnation,
        successor: &crate::auth::session_projection::AuthorizationStreamIncarnation,
    ) -> auth::AuthTransactionAttempt<(
        Option<MutationOutput>,
        crate::seed_identity::SeedInstallReceiptV1,
    )> {
        let _writer_token = match self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::ResetAndSeed)
        {
            Ok(token) => token,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        if let Err(error) = request.validate() {
            return auth::AuthTransactionAttempt::RolledBack(error);
        }
        let request_digest = match request.request_digest() {
            Ok(digest) => digest,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        let seed = request
            .artifact
            .as_ref()
            .map(crate::seed_identity::SeedArtifactV1::seed_data);
        let schema = self.schema.clone();
        let projections = self.projections.clone();
        let authorization_interlock = self.authorization_interlock.clone();
        let tx = match self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)
        {
            Ok(tx) => tx,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error.into()),
        };
        let authorization_predecessor = match auth_stream::read_authorization_version_on(&tx) {
            Ok(version) => version,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        if authorization_predecessor
            .as_ref()
            .map(|version| version.incarnation.as_str())
            != Some(predecessor.as_str())
        {
            return auth::AuthTransactionAttempt::RolledBack(SnapbackError::error(
                "SNAPBACK_AUTH_STREAM_INCARNATION_CORRUPT",
                "auth",
                "reset coordinator predecessor does not match durable authorization state",
            ));
        }
        let (seeded, receipt) = match reset_and_seed_transaction(
            &tx,
            &schema,
            projections.as_ref(),
            &self.order_field_bounds,
            seed,
            successor,
            Some((&request, &request_digest)),
        ) {
            Ok((seeded, Some(receipt))) => (seeded, receipt),
            Ok((_seeded, None)) => unreachable!("versioned reset omitted receipt"),
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        let authorization = AuthorizationCommitWitness {
            version: AuthorizationVersion {
                incarnation: successor.as_str().to_owned(),
                epoch: 0,
            },
            event: true,
            incarnation_rotated: true,
            membership_declarations: Vec::new(),
        };
        let min_commit_version = seeded.as_ref().map_or(0, |output| output.version);
        let prepared = match prepare_authorization_commit_interlock(
            &authorization,
            AuthorizationCommitImpact::AllProtectedRooms,
            authorization_interlock.as_ref(),
        ) {
            Ok(prepared) => prepared,
            Err(error) => return auth::AuthTransactionAttempt::RolledBack(error),
        };
        let committed = (seeded, receipt);
        #[cfg(test)]
        if let Err(error) = BEFORE_RESET_COMMIT_HOOK.with(|slot| {
            if let Some(hook) = slot.borrow_mut().take() {
                hook()?;
            }
            Ok::<(), SnapbackError>(())
        }) {
            return auth::AuthTransactionAttempt::RolledBack(error);
        }
        match tx.commit() {
            Ok(()) => match prepared {
                Some(prepared) => match prepared.committed(min_commit_version) {
                    Ok(()) => auth::AuthTransactionAttempt::Committed(committed),
                    Err(error) => auth::AuthTransactionAttempt::CommitUncertain(error),
                },
                None => auth::AuthTransactionAttempt::Committed(committed),
            },
            Err(error) => {
                let error = SnapbackError::from(error);
                match auth_stream::read_authorization_version_snapshot(&self.conn) {
                    Ok(durable) if durable == Some(authorization.version.clone()) => match prepared
                    {
                        Some(prepared) => match prepared.committed(min_commit_version) {
                            Ok(()) => auth::AuthTransactionAttempt::Committed(committed),
                            Err(error) => auth::AuthTransactionAttempt::CommitUncertain(error),
                        },
                        None => auth::AuthTransactionAttempt::Committed(committed),
                    },
                    Ok(durable) if durable == authorization_predecessor => {
                        drop(prepared);
                        auth::AuthTransactionAttempt::RolledBack(error)
                    }
                    Ok(_) | Err(_) => {
                        if let Some(prepared) = prepared {
                            prepared.ambiguous();
                        }
                        auth::AuthTransactionAttempt::CommitUncertain(error)
                    }
                }
            }
        }
    }

    /// Authorization-aware compatibility seam for direct storage callers.
    /// Item 5's coordinated reset chooses and durably publishes the successor
    /// stream; the exact version read after that successful cut is its proof.
    pub fn reset_and_seed_with_authorization(
        &mut self,
        seed: Option<SeedData>,
    ) -> SnapbackResult<ResetCommit> {
        let seeded = self.reset_and_seed(seed)?;
        Ok(ResetCommit {
            seeded,
            authorization: AuthorizationCommitWitness {
                version: self.authorization_version()?,
                event: true,
                incarnation_rotated: true,
                membership_declarations: Vec::new(),
            },
        })
    }

    pub fn load_cron_state(&self) -> SnapbackResult<Option<Value>> {
        let value: Option<String> = self
            .conn
            .query_row(
                "SELECT value FROM _snapback_meta WHERE key = ?1",
                params![META_CRON_STATE],
                |row| row.get(0),
            )
            .optional()?;

        value
            .map(|value| {
                serde_json::from_str(&value).map_err(|error| {
                    SnapbackError::error(
                        "SNAPBACK_CRON_STATE_PARSE_FAILED",
                        "cron",
                        "stored cron runtime state could not be parsed",
                    )
                    .with_detail("error", error.to_string())
                })
            })
            .transpose()
    }

    pub fn save_cron_state(&mut self, value: &Value) -> SnapbackResult<()> {
        let state_json = serde_json::to_string(value).map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_CRON_STATE_SERIALIZE_FAILED",
                "cron",
                "cron runtime state could not be serialized",
            )
            .with_detail("error", error.to_string())
        })?;
        self.conn.execute(
            "INSERT INTO _snapback_meta(key, value) VALUES(?1, ?2)
             ON CONFLICT(key) DO UPDATE SET value = excluded.value",
            params![META_CRON_STATE, state_json],
        )?;
        Ok(())
    }

    /// Load the served api-envelope state (LLP 0062 §5, server-composed).
    /// `current` binds the digest to the inputsHash it was composed for, so a
    /// crash between activation and this record self-heals on read: a record
    /// whose inputsHash disagrees with the active generation serves the typed
    /// absent marker instead of a stale envelope.
    pub fn load_api_envelope_state(&self) -> SnapbackResult<Option<ApiEnvelopeStateRecord>> {
        let value: Option<String> = self
            .conn
            .query_row(
                "SELECT value FROM _snapback_meta WHERE key = ?1",
                params![META_API_ENVELOPE_STATE],
                |row| row.get(0),
            )
            .optional()?;
        value
            .map(|value| {
                serde_json::from_str(&value).map_err(|error| {
                    SnapbackError::error(
                        "SNAPBACK_APP_API_STATE_PARSE_FAILED",
                        "app-api",
                        "stored api-envelope state could not be parsed",
                    )
                    .with_detail("error", error.to_string())
                })
            })
            .transpose()
    }

    /// Record the activation's envelope disposition, rotating the previous
    /// generation's envelope into the one-deep retention window LLP 0062 §5
    /// pins (the deploy race window), and dropping anything older.
    pub fn record_api_envelope(
        &mut self,
        inputs_hash: &str,
        composed: Option<(&str, &str)>, // (digest, canonical bytes)
    ) -> SnapbackResult<()> {
        let prior = self.load_api_envelope_state()?;
        let mut retained: Vec<String> = Vec::new();
        let previous = prior
            .as_ref()
            .and_then(|state| state.current.as_ref().map(|current| current.digest.clone()));
        let current = composed.map(|(digest, _)| ApiEnvelopeCurrentRecord {
            digest: digest.to_string(),
            inputs_hash: inputs_hash.to_string(),
        });
        if let Some(current) = &current {
            retained.push(current.digest.clone());
        }
        // A redeploy of the identical envelope keeps one copy and no rotation.
        let previous = previous.filter(|digest| {
            current
                .as_ref()
                .is_none_or(|current| current.digest != *digest)
        });
        if let Some(previous) = &previous {
            retained.push(previous.clone());
        }
        let state = ApiEnvelopeStateRecord { current, previous };
        let state_json = serde_json::to_string(&state).map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_APP_API_STATE_PARSE_FAILED",
                "app-api",
                "api-envelope state could not be serialized",
            )
            .with_detail("error", error.to_string())
        })?;
        let transaction = self.conn.transaction()?;
        transaction.execute(
            "INSERT INTO _snapback_meta(key, value) VALUES(?1, ?2)
             ON CONFLICT(key) DO UPDATE SET value = excluded.value",
            params![META_API_ENVELOPE_STATE, state_json],
        )?;
        if let Some((digest, canonical)) = composed {
            transaction.execute(
                "INSERT INTO _snapback_meta(key, value) VALUES(?1, ?2)
                 ON CONFLICT(key) DO UPDATE SET value = excluded.value",
                params![
                    format!("{META_API_ENVELOPE_BYTES_PREFIX}{digest}"),
                    canonical
                ],
            )?;
        }
        // Evict every stored envelope outside the retention window.
        let mut evict =
            transaction.prepare("SELECT key FROM _snapback_meta WHERE key LIKE ?1 ESCAPE '\\'")?;
        let stored: Vec<String> = evict
            .query_map(
                params![format!(
                    "{}%",
                    META_API_ENVELOPE_BYTES_PREFIX.replace('_', "\\_")
                )],
                |row| row.get::<_, String>(0),
            )?
            .collect::<Result<_, _>>()?;
        drop(evict);
        for key in stored {
            let digest = key
                .strip_prefix(META_API_ENVELOPE_BYTES_PREFIX)
                .unwrap_or_default();
            if !retained.iter().any(|kept| kept == digest) {
                transaction.execute("DELETE FROM _snapback_meta WHERE key = ?1", params![key])?;
            }
        }
        transaction.commit()?;
        Ok(())
    }

    /// The canonical bytes for a retained envelope digest, if still within
    /// the retention window.
    pub fn load_api_envelope_bytes(&self, digest: &str) -> SnapbackResult<Option<String>> {
        Ok(self
            .conn
            .query_row(
                "SELECT value FROM _snapback_meta WHERE key = ?1",
                params![format!("{META_API_ENVELOPE_BYTES_PREFIX}{digest}")],
                |row| row.get(0),
            )
            .optional()?)
    }

    /// Install or observe one generated v1 seed against the current app pair.
    /// Row effects, projection effects, identity, receipt, and idempotency
    /// evidence share this one SQLite writer transaction.
    ///
    /// @ref LLP 0109#165-executable-effect-accounting — application effects
    /// are bounded before the transaction can publish any byte.
    pub fn ensure_versioned_seed(
        &mut self,
        request: crate::seed_identity::InstallSeedRequestV1,
    ) -> SnapbackResult<crate::seed_identity::SeedEnsureResultV1> {
        let _writer_token = self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::StandaloneSeed)?;
        request.validate()?;
        validate_versioned_seed_request(
            &self.schema,
            request.requested_mode,
            Some(&request.artifact),
        )?;
        let request_digest = request.request_digest()?;
        let schema = self.schema.clone();
        let projections = self.projections.clone();
        let authorization_interlock = self.authorization_interlock.clone();
        let tx = self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        crate::seed_identity::create_infra(&tx)?;
        let current_stream = crate::seed_identity::strict_current_data_version_stream(&tx)?;

        if let Some(receipt) = crate::seed_identity::replay_completed_operation(
            &tx,
            &request.operation_id,
            &request_digest,
            current_stream.as_deref(),
        )? {
            if receipt.operation != crate::seed_identity::SeedOperationV1::Install {
                return Err(SnapbackError::error(
                    "SNAPBACK_SEED_OPERATION_ID_REUSED",
                    "seed",
                    "operation id belongs to another seed operation",
                ));
            }
            tx.rollback()?;
            return Ok(crate::seed_identity::SeedEnsureResultV1::Installed { receipt });
        }

        if let Some(stream) = current_stream.as_deref()
            && let Some(active) = crate::seed_identity::active_installation(&tx, stream)?
        {
            if active.identity.app_id == request.artifact.app_id
                && active.identity.seed_version == request.artifact.seed_version
                && active.identity.seed_digest == request.artifact.seed_digest
            {
                tx.rollback()?;
                return Ok(crate::seed_identity::SeedEnsureResultV1::Matched {
                    observation: crate::seed_identity::SeedMatchedObservationV1 {
                        format_version: crate::seed_identity::SEED_MATCHED_OBSERVATION_FORMAT_V1
                            .to_owned(),
                        outcome: "matched".to_owned(),
                        active: active.identity,
                        establishing_receipt: active.receipt,
                    },
                });
            }
            let code = if active.identity.app_id == request.artifact.app_id
                && active.identity.seed_version == request.artifact.seed_version
            {
                "SNAPBACK_SEED_VERSION_REUSED"
            } else {
                "SNAPBACK_SEED_MIGRATION_REQUIRED"
            };
            return Err(SnapbackError::error(
                code,
                "seed",
                "another versioned seed identity is active in the current data stream",
            ));
        }

        let occupancy = versioned_seed_target_occupancy(&tx, &schema, &request.artifact)?;
        if occupancy.iter().any(|occupied| *occupied) {
            let code = if occupancy.iter().all(|occupied| *occupied) {
                "SNAPBACK_SEED_NONEMPTY_UNTRACKED"
            } else {
                "SNAPBACK_SEED_PARTIAL_UNTRACKED"
            };
            return Err(SnapbackError::error(
                code,
                "seed",
                "seed targets contain application rows without active versioned \
                 identity; recover with the versioned reset-install \
                 (POST /_snapback/api/app/seed/reset-install-v1) or start from \
                 a fresh database — a raw app reset with an inline seed \
                 produces exactly this state",
            ));
        }

        let predecessor_stream = current_stream.clone();
        let stream = match current_stream {
            Some(stream) => stream,
            None => auth_invalidation::ensure_data_version_stream_in(&tx)?,
        };
        let current_version = current_version_on(&tx)?;
        let next_version = next_storage_version(current_version)?;
        let touched = request.artifact.tables.keys().cloned().collect();
        validate_touched_managed_tables(&tx, &schema, &touched, current_version)?;
        preflight_membership_activation_sources(&tx, &schema, current_version)?;
        // @ref LLP 0109#17-dated-amendment-seed-asset-fixtures-2026-07-31 —
        //   fixtures finalize strictly before rows install: placeholders
        //   resolve through the ingestion mapping inside this transaction,
        //   and any missing or stale mapping refuses the whole ensure with
        //   zero row effects.
        let seed_data = crate::assets::resolve_seed_fixture_placeholders(
            &tx,
            &schema,
            &request.artifact.tables,
            request.asset_fixtures.as_ref(),
        )?;
        let mut changes = seed_into_transaction(
            &tx,
            &schema,
            seed_data,
            next_version,
            &self.order_field_bounds,
        )?;
        let direct_application_rows = changes.len();
        if !projections.is_empty() {
            maintain_projections_in_tx(
                &tx,
                &schema,
                projections.as_ref(),
                &mut changes,
                &BTreeMap::new(),
                next_version,
                now_millis(),
                &self.order_field_bounds,
                ProjectionEffectCeiling::VersionedSeedV1,
            )?;
        }
        let derived_projection_rows = changes.len().saturating_sub(direct_application_rows);
        let total_application_effects = crate::seed_identity::checked_application_effects(
            direct_application_rows,
            derived_projection_rows,
        )?;
        maintain_derived_indexes_in_tx(&tx, &schema, &changes, next_version)?;
        validate_membership_activation(&tx, &schema, next_version)?;
        if !changes.is_empty() {
            set_version(&tx, next_version)?;
        }
        let receipt = crate::seed_identity::SeedInstallReceiptV1 {
            format_version: crate::seed_identity::SEED_RECEIPT_FORMAT_V1.to_owned(),
            operation_id: request.operation_id.clone(),
            request_digest,
            operation: crate::seed_identity::SeedOperationV1::Install,
            outcome: crate::seed_identity::SeedOutcomeV1::Installed,
            app_id: request.artifact.app_id.clone(),
            seed_version: Some(request.artifact.seed_version.clone()),
            seed_digest: Some(request.artifact.seed_digest.clone()),
            schema_hash: required_versioned_seed_schema_hash(&schema)?,
            data_version_stream: stream,
            direct_application_rows,
            derived_projection_rows,
            total_application_effects,
            reset_deleted_rows: 0,
        };
        crate::seed_identity::store_installation(&tx, &request.artifact, &receipt)?;
        crate::seed_identity::store_completed_operation(
            &tx,
            predecessor_stream.as_deref(),
            &receipt,
        )?;
        crate::seed_identity::best_effort_prune_history(&tx, &receipt.data_version_stream);
        let authorization_predecessor = auth_stream::read_authorization_version_on(&tx)?;
        let authorization = authorization::authorization_commit_hook_in(
            &tx,
            authorization::AuthorizationCommitCause::AppWrites {
                schema: &schema,
                changes: &changes,
            },
        )?;
        let version = if changes.is_empty() {
            current_version
        } else {
            next_version
        };
        commit_with_authorization_interlock(
            tx,
            &authorization,
            AuthorizationCommitImpact::AppWrites {
                schema: &schema,
                changes: &changes,
            },
            authorization_predecessor,
            version,
            authorization_interlock,
        )?;
        Ok(crate::seed_identity::SeedEnsureResultV1::Installed { receipt })
    }

    /// Read-only classification for the v1 seed family. This uses a deferred
    /// transaction and rolls it back without creating stream metadata.
    pub fn preview_versioned_seed(
        &mut self,
        request: crate::seed_identity::SeedPreviewRequestV1,
    ) -> SnapbackResult<crate::seed_identity::SeedPreviewResultV1> {
        request.validate()?;
        validate_versioned_seed_request(
            &self.schema,
            request.requested_mode,
            request.artifact.as_ref(),
        )?;
        let schema = self.schema.clone();
        let tx = self.conn.transaction()?;
        let stream = crate::seed_identity::strict_current_data_version_stream(&tx)?;
        let active = match stream.as_deref() {
            Some(stream) => crate::seed_identity::active_installation(&tx, stream)?,
            None => None,
        };
        let direct = request
            .artifact
            .as_ref()
            .map(crate::seed_identity::SeedArtifactV1::row_count)
            .transpose()?
            .unwrap_or(0);
        let reset_deleted_rows = if matches!(
            request.operation,
            crate::seed_identity::SeedPreviewOperationV1::ResetInstall
                | crate::seed_identity::SeedPreviewOperationV1::Clear
        ) {
            count_physical_application_rows(&tx)?
        } else {
            0
        };
        let mut state = "installable".to_owned();
        let mut diagnostic_code = None;
        if matches!(
            request.operation,
            crate::seed_identity::SeedPreviewOperationV1::Install
        ) {
            match (&active, request.artifact.as_ref()) {
                (Some(active), Some(artifact))
                    if active.identity.app_id == artifact.app_id
                        && active.identity.seed_version == artifact.seed_version
                        && active.identity.seed_digest == artifact.seed_digest =>
                {
                    state = "matched".to_owned();
                }
                (Some(active), Some(artifact))
                    if active.identity.app_id == artifact.app_id
                        && active.identity.seed_version == artifact.seed_version =>
                {
                    state = "refused".to_owned();
                    diagnostic_code = Some("SNAPBACK_SEED_VERSION_REUSED".to_owned());
                }
                (Some(_), Some(_)) => {
                    state = "refused".to_owned();
                    diagnostic_code = Some("SNAPBACK_SEED_MIGRATION_REQUIRED".to_owned());
                }
                (None, Some(artifact)) => {
                    let occupancy = versioned_seed_target_occupancy(&tx, &schema, artifact)?;
                    if occupancy.iter().any(|occupied| *occupied) {
                        state = "refused".to_owned();
                        diagnostic_code = Some(
                            if occupancy.iter().all(|occupied| *occupied) {
                                "SNAPBACK_SEED_NONEMPTY_UNTRACKED"
                            } else {
                                "SNAPBACK_SEED_PARTIAL_UNTRACKED"
                            }
                            .to_owned(),
                        );
                    }
                }
                _ => unreachable!("preview validation closed operation/artifact combinations"),
            }
        } else if let Some(expected) = request.expected_data_version_stream.as_ref()
            && !crate::seed_identity::expected_stream_matches(expected, stream.as_deref())
        {
            state = "refused".to_owned();
            diagnostic_code = Some("SNAPBACK_SEED_OPERATION_HISTORICAL".to_owned());
        } else {
            state = match request.operation {
                crate::seed_identity::SeedPreviewOperationV1::ResetInstall => {
                    "reset-installable".to_owned()
                }
                crate::seed_identity::SeedPreviewOperationV1::Clear => "clearable".to_owned(),
                crate::seed_identity::SeedPreviewOperationV1::Install => unreachable!(),
            };
        }
        let current = active.as_ref().map(|active| active.identity.clone());
        tx.rollback()?;
        let mut derived = if state == "matched" {
            active
                .as_ref()
                .map_or(0, |active| active.identity.derived_projection_rows)
        } else {
            0
        };
        let reset_first = matches!(
            request.operation,
            crate::seed_identity::SeedPreviewOperationV1::ResetInstall
        );
        if let Some(artifact) = request.artifact.as_ref()
            && (reset_first || state == "installable")
        {
            derived = simulate_versioned_seed_projection_rows(
                self,
                &schema,
                self.projections.as_ref(),
                artifact,
                reset_first,
            )?;
        }
        let total = direct.checked_add(derived).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_SEED_EFFECT_LIMIT_EXCEEDED",
                "seed",
                "versioned seed application-effect count overflowed",
            )
        })?;
        if total > crate::seed_identity::VERSIONED_SEED_MAX_EFFECTS_V1 {
            state = "refused".to_owned();
            diagnostic_code = Some("SNAPBACK_SEED_EFFECT_LIMIT_EXCEEDED".to_owned());
        }
        let requested = request.artifact.as_ref().and_then(|artifact| {
            stream
                .as_ref()
                .map(|stream| preview_identity(artifact, stream, &schema, direct, derived))
        });
        Ok(crate::seed_identity::SeedPreviewResultV1 {
            state,
            diagnostic_code,
            current,
            requested,
            direct_application_rows: direct,
            derived_projection_rows: derived,
            total_application_effects: total,
            reset_deleted_rows,
        })
    }

    pub fn seed(&mut self, seed: SeedData) -> SnapbackResult<MutationOutput> {
        self.seed_with_authorization(seed)
            .map(|commit| commit.output)
    }

    pub(crate) fn preview_seed_changes(
        &mut self,
        seed: SeedData,
    ) -> SnapbackResult<Vec<ChangedRow>> {
        let _writer_token = self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::DryRun)?;
        let schema = self.schema.clone();
        let tx = self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        let current_version = current_version_on(&tx)?;
        let next_version = next_storage_version(current_version)?;
        let touched = seed.tables.keys().cloned().collect();
        validate_touched_managed_tables(&tx, &schema, &touched, current_version)?;
        preflight_membership_activation_sources(&tx, &schema, current_version)?;
        let changes = seed_into_transaction(
            &tx,
            &schema,
            seed,
            next_version,
            &self.order_field_bounds,
        )?;
        maintain_derived_indexes_in_tx(&tx, &schema, &changes, next_version)?;
        validate_membership_activation(&tx, &schema, next_version)?;
        tx.rollback()?;
        Ok(changes)
    }

    pub fn seed_with_authorization(&mut self, seed: SeedData) -> SnapbackResult<SeedCommit> {
        let _writer_token = self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::StandaloneSeed)?;
        let schema = self.schema.clone();
        let authorization_interlock = self.authorization_interlock.clone();
        let tx = self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        // @ref LLP 0007#commit-version-graduation-dk-2-decided-2026-07-02 — SQLite's writer
        // reservation is the local target's version-allocation fence.
        let current_version = current_version_on(&tx)?;
        let next_version = next_storage_version(current_version)?;
        let touched = seed.tables.keys().cloned().collect();
        validate_touched_managed_tables(&tx, &schema, &touched, current_version)?;
        preflight_membership_activation_sources(&tx, &schema, current_version)?;
        let changes =
            seed_into_transaction(&tx, &schema, seed, next_version, &self.order_field_bounds)?;
        // The standalone seed API has the same invariant obligations as a
        // deployment seed; it cannot bypass membership activation checks just
        // because DDL was already active.
        validate_membership_activation(&tx, &schema, next_version)?;
        let changed_count = changes.len();

        if changed_count > 0 {
            maintain_derived_indexes_in_tx(&tx, &schema, &changes, next_version)?;
            set_version(&tx, next_version)?;
        }
        let authorization_predecessor = auth_stream::read_authorization_version_on(&tx)?;
        let authorization = authorization::authorization_commit_hook_in(
            &tx,
            authorization::AuthorizationCommitCause::AppWrites {
                schema: &schema,
                changes: &changes,
            },
        )?;
        let version = if changed_count > 0 {
            next_version
        } else {
            current_version
        };
        commit_with_authorization_interlock(
            tx,
            &authorization,
            AuthorizationCommitImpact::AppWrites {
                schema: &schema,
                changes: &changes,
            },
            authorization_predecessor,
            version,
            authorization_interlock,
        )?;

        Ok(SeedCommit {
            output: MutationOutput {
                version,
                changed_count,
                result: Value::Null,
                ctx_ledger: None,
                settlement_mint_observations: Vec::new(),
                settlement_time_observation: None,
                settlement_sequence_allocations: Vec::new(),
            },
            authorization,
        })
    }

    pub fn query(&self, plan: &QueryPlan, input: &HandlerInput) -> SnapbackResult<QueryOutput> {
        query_on(&self.conn, &self.schema, plan, input)
    }

    /// One ceiling-bounded batch of the privileged migration scan against a
    /// pinned read snapshot (LLP 0081 §3). The Wave-2 executor instead calls
    /// [`migration_keyset_scan_batch_on`] inside its own batch transaction.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) fn migration_keyset_scan_batch(
        &self,
        request: &MigrationKeysetScanRequestV1,
        checkpoint: Option<&MigrationKeysetScanCheckpointV1>,
    ) -> SnapbackResult<MigrationKeysetScanBatch> {
        self.with_pinned_read_view(|db| match db {
            DbRead::Pinned { conn, schema } => {
                migration_keyset_scan_batch_on(conn, schema, request, checkpoint)
            }
            DbRead::Live(db) => {
                migration_keyset_scan_batch_on(&db.conn, &db.schema, request, checkpoint)
            }
        })
    }

    /// Snapshot-pinned preview facts for LLP 0081's separately digested
    /// observation. Each current v1 plan step declares at most one read table;
    /// its row summary inspects no more than `max_affected_rows + 1` rows. The
    /// extra row is the bounded signal that the reviewed ceiling is already
    /// exceeded, without turning preview into an unbounded application scan.
    ///
    /// @ref LLP 0081#2-canonical-plan-and-approval — preview observations
    /// carry the target head and bounded aggregate preconditions from one
    /// snapshot, but never add authority to the sealed plan.
    pub(crate) fn migration_preview_observation_facts(
        &self,
        steps: &[crate::migration::MigrationStepRecord],
        max_affected_rows: u64,
    ) -> SnapbackResult<(u64, BTreeMap<String, u64>)> {
        self.with_pinned_read_view(|view| {
            let head = view.current_version()?;
            let limit = max_affected_rows
                .saturating_add(1)
                .min(i64::MAX as u64) as i64;
            let mut table_rows = BTreeMap::<String, u64>::new();
            let mut precondition_rows = BTreeMap::new();
            for record in steps {
                let [table] = record.reads.as_slice() else {
                    // The v1 planner currently emits zero or one read table.
                    // A later multi-source step needs a versioned observation
                    // shape instead of collapsing several counts into one.
                    continue;
                };
                let rows = match table_rows.get(table) {
                    Some(rows) => *rows,
                    None => {
                        let _ = schema_table(view.schema(), table)?;
                        let quoted = quote_ident(table)?;
                        let observed: i64 = view.conn().query_row(
                            &format!(
                                "SELECT COUNT(*) FROM (SELECT 1 FROM {quoted} LIMIT ?1)"
                            ),
                            params![limit],
                            |row| row.get(0),
                        )?;
                        let rows = u64::try_from(observed).map_err(|_| {
                            SnapbackError::error(
                                "SNAPBACK_MIGRATION_PRECONDITION_FAILED",
                                "storage",
                                format!(
                                    "preview row summary for {table} was outside the non-negative integer domain"
                                ),
                            )
                        })?;
                        table_rows.insert(table.clone(), rows);
                        rows
                    }
                };
                precondition_rows.insert(record.id.clone(), rows);
            }
            Ok((head, precondition_rows))
        })
    }

    /// Resume an interrupted migration-cleanup tail at reopen (LLP 0081
    /// §4: a crash after release reopens only the successor and resumes
    /// cleanup). Inventory-driven — no artifact required.
    pub(crate) fn resume_pending_migration_cleanup(&mut self) -> SnapbackResult<Option<Value>> {
        let _writer_token = self
            .writer_authority
            .enter(write_authority::LocalWriterLaneV1::MigrationExecutor)?;
        let schema = self.schema.clone();
        migration_executor::resume_pending_cleanup(&mut self.conn, &schema)
    }

    /// Install the active maintained-projection set (LLP 0080 §5). Called by
    /// function-manifest activation after validation; every mutation path on
    /// this database maintains these outputs in its own commit.
    pub(crate) fn set_projections(
        &mut self,
        plans: Vec<crate::manifest::MaintainedProjectionPlan>,
    ) {
        self.projections = Arc::new(plans);
    }

    /// Refuse adoption when existing rows already exceed a newly declared
    /// order-field ceiling. This is deliberately read-only; callers install
    /// the map only after the complete function generation passes preflight.
    pub(crate) fn validate_order_field_bounds(
        &self,
        bounds: &BTreeMap<(String, String), u64>,
    ) -> SnapbackResult<()> {
        for ((table, field), maximum) in bounds {
            let oversized = self
                .conn
                .query_row(
                    &format!(
                        "SELECT _id FROM {} WHERE {} IS NOT NULL AND length(CAST({} AS BLOB)) > ?1 LIMIT 1",
                        quote_ident(table)?,
                        quote_ident(field)?,
                        quote_ident(field)?,
                    ),
                    params![i64::try_from(*maximum).map_err(|_| {
                        SnapbackError::error(
                            "SNAPBACK_FUNCTION_SCHEMA_REFERENCE_INVALID",
                            "runtime",
                            format!(
                                "order-field bound for {table}.{field} exceeds the SQLite integer domain"
                            ),
                        )
                    })?],
                    |row| row.get::<_, String>(0),
                )
                .optional()?;
            if let Some(row_id) = oversized {
                return Err(order_field_max_encoded_bytes_exceeded(
                    table, field, &row_id, *maximum,
                ));
            }
        }
        Ok(())
    }

    /// Refuse sequence activation over brownfield scope rows until every
    /// present row has exactly one active LLP 0110 incarnation and no active
    /// registry row points at a missing scope. New central-writer inserts
    /// already mint these facts; this gate makes adoption of older rows
    /// explicit instead of silently blessing them.
    ///
    /// @ref LLP 0135#11-counter-identity-and-scope — declaring a counter
    ///   enrolls its scope in the shared relation-incarnation authority, and
    ///   brownfield rows require reviewed backfill before activation.
    pub(crate) fn validate_sequence_scope_activation(
        &self,
        scope_tables: &BTreeSet<String>,
    ) -> SnapbackResult<()> {
        for table in scope_tables {
            let table_sql = quote_ident(table)?;
            let missing_or_duplicate_active = self
                .conn
                .query_row(
                    &format!(
                        "SELECT s._id
                           FROM {table_sql} s
                      LEFT JOIN _snapback_relation_incarnations_v1 r
                             ON r.table_name = ?1
                            AND r.row_id = s._id
                            AND r.active = 1
                       GROUP BY s._id
                         HAVING count(r.incarnation) != 1
                          LIMIT 1"
                    ),
                    params![table],
                    |row| row.get::<_, String>(0),
                )
                .optional()?;
            if let Some(row_id) = missing_or_duplicate_active {
                return Err(SnapbackError::error(
                    "SNAPBACK_RELATION_ACTIVATION_BACKFILL_REQUIRED",
                    "schema",
                    "each sequence scope row must have exactly one active incarnation",
                )
                .with_details(json!({
                    "scopeTable": table,
                    "rowId": row_id,
                    "direction": "scope-to-registry",
                })));
            }

            let dangling_active = self
                .conn
                .query_row(
                    &format!(
                        "SELECT r.row_id
                           FROM _snapback_relation_incarnations_v1 r
                      LEFT JOIN {table_sql} s ON s._id = r.row_id
                          WHERE r.table_name = ?1
                            AND r.active = 1
                            AND s._id IS NULL
                          LIMIT 1"
                    ),
                    params![table],
                    |row| row.get::<_, String>(0),
                )
                .optional()?;
            if let Some(row_id) = dangling_active {
                return Err(SnapbackError::error(
                    "SNAPBACK_RELATION_ACTIVATION_BACKFILL_REQUIRED",
                    "schema",
                    "an active sequence scope incarnation has no present row",
                )
                .with_details(json!({
                    "scopeTable": table,
                    "rowId": row_id,
                    "direction": "registry-to-scope",
                })));
            }
            validate_active_sequence_scope_fact_grammar(&self.conn, table)?;
        }
        Ok(())
    }

    /// Pure activation preflight used before projection rebuilds. Missing
    /// markers are provisionally admissible only for an already-active
    /// predecessor scope or a physically empty table; the final installer
    /// persists that authority transactionally after all other preflight work.
    pub(crate) fn validate_sequence_declaration_preflight(
        &self,
        declarations: &BTreeMap<String, crate::manifest::SequenceDeclaration>,
        trusted_active_generation: bool,
    ) -> SnapbackResult<()> {
        let mut predecessor_tables = BTreeSet::new();
        let successor_tables = sequence_scope_tables_from_declarations(declarations);
        if trusted_active_generation {
            predecessor_tables.extend(sequence_scope_tables_from_declarations(
                &self.sequence_declarations,
            ));
            predecessor_tables.extend(successor_tables.iter().copied());
        }
        for table in &successor_tables {
            let enrolled = self
                .conn
                .query_row(
                    "SELECT 1 FROM _snapback_sequence_scope_enrollments_v1 WHERE table_name = ?1",
                    params![table],
                    |_| Ok(()),
                )
                .optional()?
                .is_some();
            if !enrolled
                && !predecessor_tables.contains(table)
                && !schema_relation_parent_tables(&self.schema).contains(table)
            {
                let existing_rows = self.conn.query_row(
                    &format!("SELECT COUNT(*) FROM {}", quote_ident(table)?),
                    [],
                    |row| row.get::<_, i64>(0),
                )?;
                if existing_rows != 0 {
                    return Err(SnapbackError::error(
                        "SNAPBACK_RELATION_ACTIVATION_BACKFILL_REQUIRED",
                        "schema",
                        "a newly enrolled sequence scope has pre-existing rows without reviewed backfill authority",
                    )
                    .with_details(json!({
                        "parentTable": table,
                        "existingRows": existing_rows,
                        "enrollmentMarker": false,
                    })));
                }
            }
        }
        self.validate_sequence_scope_activation(
            &successor_tables.into_iter().map(ToOwned::to_owned).collect(),
        )?;
        validate_sequence_counter_rows(&self.conn, declarations)
    }

    pub(crate) fn set_order_field_bounds(
        &mut self,
        bounds: BTreeMap<(String, String), u64>,
    ) {
        self.order_field_bounds = Arc::new(bounds);
    }

    pub(crate) fn install_sequence_declarations(
        &mut self,
        declarations: BTreeMap<String, crate::manifest::SequenceDeclaration>,
        trusted_active_generation: bool,
    ) -> SnapbackResult<()> {
        let mut predecessor = BTreeMap::new();
        if trusted_active_generation {
            predecessor.extend(self.sequence_declarations.as_ref().clone());
            predecessor.extend(declarations.clone());
        }
        let trusted_relation_parent_tables = schema_relation_parent_tables(&self.schema)
            .into_iter()
            .map(ToOwned::to_owned)
            .collect();
        let tx = self
            .conn
            .transaction_with_behavior(TransactionBehavior::Immediate)?;
        preflight_sequence_enrollments(
            &tx,
            &self.schema,
            &trusted_relation_parent_tables,
            &predecessor,
            &declarations,
        )?;
        validate_sequence_activation(&tx, &self.schema, &declarations)?;
        tx.commit()?;
        self.sequence_declarations = Arc::new(declarations);
        Ok(())
    }

    /// Execute a closed relational plan under `root-window-v1`.
    ///
    /// @ref LLP 0080#2-portable-evaluation-semantics — the normative
    ///   pipeline: visible root filter → root order → take N roots → join +
    ///   joined visibility → projection. Both source predicates execute
    ///   inside one pinned read snapshot; `take` bounds consumed authorized
    ///   roots; `inner` omits an unmatched or invisible joined row without
    ///   refilling the page; `left` emits null joined leaves.
    pub fn query_relational(
        &self,
        plan: &crate::manifest::RelationalQueryPlan,
        input: &HandlerInput,
        cursor: Option<&KeysetAfter>,
    ) -> SnapbackResult<(QueryOutput, Option<KeysetAfter>)> {
        self.with_pinned_read_view(|db| query_relational_on(&db, plan, input, cursor))
    }

