    /// Read a page of a table for the admin data explorer.
    ///
    /// Schema-aware and read-only: the table must be a known schema table, rows
    /// decode through the same field-type rules as `query`, and ordering is a
    /// stable `(_createdAt, _id)` so paging is deterministic. This is the paved
    /// read path; it is not raw SQL.
    ///
    /// @ref LLP 0017#durable-data-exploration-and-edits — read-only exploration
    /// through schema-aware storage with system fields shown.
    pub fn scan_table(
        &self,
        table: &str,
        limit: usize,
        offset: usize,
    ) -> SnapbackResult<TableScan> {
        let table_manifest = schema_table(&self.schema, table)?;
        with_pinned_read_snapshot(&self.conn, |conn| {
            let snapshot_version = current_version_on(conn)?;
            let quoted = quote_ident(table)?;

            let total: i64 =
                conn.query_row(&format!("SELECT COUNT(*) FROM {quoted}"), [], |row| {
                    row.get(0)
                })?;

            let sql = format!(
                "SELECT * FROM {quoted} ORDER BY \"_createdAt\" ASC, \"_id\" ASC LIMIT ?1 OFFSET ?2"
            );
            let mut statement = conn.prepare(&sql)?;
            let columns = statement
                .column_names()
                .into_iter()
                .map(ToOwned::to_owned)
                .collect::<Vec<_>>();
            let mut sql_rows = statement.query(params![limit as i64, offset as i64])?;
            let mut rows = Vec::new();
            while let Some(row) = sql_rows.next()? {
                let document = row_to_document(row, table_manifest, &columns)?;
                validate_document_version_at_most(&document, snapshot_version, table)?;
                rows.push(document);
            }

            let mut display_columns = vec!["_id".to_owned()];
            display_columns.extend(table_manifest.fields.iter().map(|field| field.name.clone()));
            display_columns.extend([
                "_version".to_owned(),
                "_createdAt".to_owned(),
                "_updatedAt".to_owned(),
            ]);

            Ok(TableScan {
                table: table.to_owned(),
                columns: display_columns,
                rows,
                total: total as usize,
                limit,
                offset,
            })
        })
    }

    pub fn execute_mutation(
        &mut self,
        plan: &MutationPlan,
        input: &HandlerInput,
    ) -> SnapbackResult<MutationCommit> {
        Ok(self
            .execute_mutation_plan(plan, input, true, None, None)?
            .commit)
    }

    /// Execute a host plan with lifecycle checks throughout its finite step
    /// loops, then acquire a caller-owned guard only for the final SQLite
    /// commit. Detached actions use this to keep untrusted/data-dependent plan
    /// execution outside their abandonment gate while still linearizing the
    /// durable commit against the public watchdog.
    pub(crate) fn execute_mutation_guarded<G, Check, BeforeCommit>(
        &mut self,
        plan: &MutationPlan,
        input: &HandlerInput,
        check_live: Check,
        before_commit: BeforeCommit,
    ) -> SnapbackResult<MutationCommit>
    where
        Check: Fn() -> SnapbackResult<()>,
        BeforeCommit: FnOnce() -> SnapbackResult<G>,
    {
        require_covered_mutation_identity_for_lane(
            &self.conn,
            CoveredMutationLaneV1::Ordinary,
            None,
        )?;
        Ok(self
            .execute_mutation_plan_with_lifecycle_and_settlement_time(
                write_authority::LocalWriterLaneV1::OrdinaryHostPlan,
                plan,
                input,
                true,
                None,
                None,
                &check_live,
                before_commit,
            )?
            .commit)
    }

    pub fn execute_mutation_idempotent(
        &mut self,
        plan: &MutationPlan,
        input: &HandlerInput,
        identity: &ClientMutationIdentity,
    ) -> SnapbackResult<MutationCommit> {
        require_covered_mutation_identity_for_lane(
            &self.conn,
            CoveredMutationLaneV1::Ordinary,
            Some(identity),
        )?;
        if let Some(output) = self.client_mutation_result(identity)? {
            let sequence_allocations = output.settlement_sequence_allocations.clone();
            return Ok(MutationCommit {
                output,
                changes: Vec::new(),
                read_dependencies: Vec::new(),
                write_dependencies: Vec::new(),
                job_enqueues: Vec::new(),
                job_changes: Vec::new(),
                sequence_allocations,
                authorization: None,
            });
        }
        Ok(self
            .execute_mutation_plan(plan, input, true, Some(identity), None)?
            .commit)
    }

